from collections.abc import Mapping


def advance_actors(width, height, actors, deltas):
    for name, value in (("width", width), ("height", height)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an integer")
        if value <= 0:
            raise ValueError(f"{name} must be positive")
    if not isinstance(deltas, Mapping):
        raise TypeError("deltas must be a mapping")
    try:
        source = list(actors)
    except TypeError as exc:
        raise TypeError("actors must be iterable") from exc
    parsed = []
    ids = set()
    for actor in source:
        if not isinstance(actor, dict):
            raise TypeError("each actor must be a dictionary")
        if set(actor) != {"id", "x", "y"}:
            raise ValueError("actor keys must be id, x, and y")
        actor_id, x, y = actor["id"], actor["x"], actor["y"]
        if not isinstance(actor_id, str) or not actor_id or actor_id in ids:
            raise ValueError("actor IDs must be unique non-empty strings")
        if any(isinstance(v, bool) or not isinstance(v, int) for v in (x, y)):
            raise TypeError("coordinates must be integers")
        if not (0 <= x < width and 0 <= y < height):
            raise ValueError("actor is outside the board")
        ids.add(actor_id)
        parsed.append((actor_id, x, y))
    if any(actor_id not in ids for actor_id in deltas):
        raise ValueError("delta references an unknown actor")
    moves = {}
    for actor_id, delta in deltas.items():
        if isinstance(delta, (str, bytes)):
            raise TypeError("delta must be a pair")
        try:
            pair = tuple(delta)
        except TypeError as exc:
            raise TypeError("delta must be a pair") from exc
        if len(pair) != 2:
            raise ValueError("delta must contain two values")
        if any(isinstance(v, bool) or not isinstance(v, int) for v in pair):
            raise TypeError("delta values must be integers")
        moves[actor_id] = pair
    result = []
    for actor_id, x, y in parsed:
        dx, dy = moves.get(actor_id, (0, 0))
        nx, ny = x + dx, y + dy
        if 0 <= nx <= width and 0 <= ny <= height:
            x, y = nx, ny
        result.append({"id": actor_id, "x": x, "y": y})
    return result

